func dispose() -> void:
	if rd == null: return
	for rid in retained: rd.free_rid(rid)
	retained.clear()
	if pipeline.is_valid(): rd.free_rid(pipeline)
	if compute_shader.is_valid(): rd.free_rid(compute_shader)
