func _ready():
	task = _host_config("task.json")
	demo = _host_config("demo.json")
	stage = get_node("Stage")
	effect_root = get_node("EffectRoot")
	camera = stage.get_node("CameraRig/Camera3D")
	if task.task_id.begins_with("E"): _create_capture_views()
