		cam.global_transform=camera.global_transform
		cam.fov=camera.fov
		cam.near=camera.near
		cam.far=camera.far

func background(consumer: String) -> Texture2D:
	var name = "OpaqueCapture" if consumer == "rear" else "RearCapture"
