        sum += amplitude*noise3(p*frequency);
        weight += amplitude;
        amplitude *= gain;
        frequency *= lacunarity;
    }
    return sum / max(weight, 0.000001);
}
vec4 burn_field(vec3 p, vec3 origin, float time, float t0, float r0, float speed,
                float amplitude, float frequency, int octaves, float gain, float lacunarity,
                float width, bool enabled) {
    float n = fbm3(p, frequency, octaves, gain, lacunarity);
    float radius = r0 + speed*max(time-t0,0.0);
    float s = length(p-origin) - radius + amplitude*n;
    float w = max(width,0.000001);
    float c = 1.0-smoothstep(-w,w,s);
    float e = 1.0-smoothstep(0.0,w,abs(s));
    if (!enabled || time < t0) { c=0.0; e=0.0; }
    return vec4(n,s,c,e);
