                   mix(corner(i+ivec3(0,1,1),f-vec3(0,1,1)),corner(i+vec3(1,1,1),f-vec3(1,1,1)),u.x),u.y),u.z);
}
float fbm3(vec3 p, float frequency, int octaves, float gain, float lacunarity) {
    float sum = 0.0;
    float amplitude = 1.0;
    float weight = 0.0;
    for (int j=0; j<octaves; j++) {
        sum += amplitude*noise3(p*frequency);
        weight += amplitude;
        amplitude *= gain;
        frequency *= lacunarity;
    }
    return sum / max(weight, 0.000001);
