			return {"status":"OK","file":name,"shape":value.shape,"fields":value.fields,"dtype":"<f4","time":value.get("time",0),"origin":"actual_gpu_readback"}
		if value.get("status","") == "OK" and value.has("texture") and value.texture is Texture2D:
