			if image.get_format() not in [Image.FORMAT_RF,Image.FORMAT_RGF,Image.FORMAT_RGBF,Image.FORMAT_RGBAF]:
				return {"status":"ERROR","error":"numeric texture must have float32 channels"}
			serial += 1
