void fragment() {
    vec3 p = reference_position;
    vec4 field = burn_field(p,origin_ref,burn_time,t0,R0,speed,noise_amplitude,base_frequency,octaves,gain,lacunarity,width,enabled);
    // The original wood texture remains visible in the unburnt part.
    float warp = noise3(vec3(p.x*3.0,p.y*0.8,2.3));
    float grain = sin(p.x*125.0+warp*12.0+sin(p.y*2.5)*1.3);
    float fine = noise3(vec3(p.x*90.0,p.y*9.0,5.4));
    vec3 wood = texture(wood_base,UV).rgb * (0.87+0.11*grain+0.1*fine);
    float cells = noise3(p*26.0+vec3(3.2,4.1,1.8));
    float cracks = smoothstep(0.045,0.1,abs(cells));
    vec3 coal = mix(vec3(0.005,0.004,0.003),vec3(0.041,0.029,0.021),cracks);
    coal *= 0.85+0.3*fine;
    float charred = smoothstep(0.0,0.85,field.z);
    ALBEDO = mix(wood,coal,charred);
